157	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
158	            .buildAndExpand(pet.getId()).toUri());
159	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
160	    }
161	
162	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
163	    @Override
164	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
165	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
166	        if (currentOwner != null) {
167	            Pet currentPet = this.clinicService.findPetById(petId);
